SELECT 'gongkao', '适用对象', 'kp-xingce-language-cloze-idiom-target-object', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "成语辨析：适用对象"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多成语有极其严苛的使用范围。用来修饰人、物还是事，绝不能乱套。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、高频专属对象"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【巧夺天工】：只能形容【人工制作的物品】极其精美。绝不能用来形容自然风光！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【鬼斧神工】：同上，只能形容【人工】。形容自然风光必须用【鬼斧神工】（错！自然风光叫【大自然的鬼斧神工】或【大自然的杰作】？错！形容大自然用【巧夺天工】更是错上加错。大自然只能叫【浑然天成】或【造化钟神秀】！）"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【美轮美奂】：只能形容【戏曲或建筑】极其华美。不能形容美女！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【汗牛充栋】：只能形容【书多】。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【炙手可热】：形容【权势大，气焰盛】。绝对不能用来形容商品畅销（要用走俏/抢手）！"}]}]}]}]}$$ AS jsonb), NULL, '适用对象的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "适用对象"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_idiom_target_object", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
